(()=>{if(window.matchMedia("(prefers-reduced-motion: reduce)").matches||(document.querySelectorAll(".ps-hero-inner,.web-home-hero .web-hero-grid").forEach(e=>e.classList.add("ref-enter")),!("IntersectionObserver"in window)))return;const o=new IntersectionObserver(e=>{e.forEach(r=>{r.isIntersecting&&(r.target.classList.add("ref-reveal"),o.unobserve(r.target))})},{threshold:.08});document.querySelectorAll(".ps-unit-card-light,.ps-unit-card-pro,.ps-daily-card,.ps-fnb-card,.web-console-card,.web-package,.web-info-card,.web-footer-invite").forEach(e=>o.observe(e))})();
